import React, { useEffect, useState } from "react";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import API_BASE_URL from "../config";
import "../styles/UserPages.css";

const RentalOrders = () => {
  const [orders, setOrders] = useState([]);
  const userId = sessionStorage.getItem("userId");

  useEffect(() => {
    fetch(`${API_BASE_URL}/api/rentals/orders/${userId}`)
      .then((res) => res.json())
      .then((data) => setOrders(data));
  }, [userId]);

  return (
    <>
      <Navbar />
      <div className="page-container">
        <div className="page-header">
          <h2>My Rental Orders</h2>
        </div>
        {orders.length === 0 ? (
          <p>You haven't rented anything yet.</p>
        ) : (
          <div className="card-grid">
            {orders.map((order) => (
              <div key={order.id} className="card">
                {order.image && <img src={order.image} alt="Rental" className="card-image" />}
                <h4>{order.title}</h4>
                <p>{order.description}</p>
                <p><strong>${order.total_price}</strong> / {order.rental_duration}</p>
                <p><em>Rented on:</em> {new Date(order.created_at).toLocaleDateString()}</p>
              </div>
            ))}
          </div>
        )}
      </div>
      <Footer />
    </>
  );
};

export default RentalOrders;
